import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";

const AdmInfProf = () => {
  const { id } = useParams();
  const [editMode, setEditMode] = useState(false);
  const [professor, setProfessor] = useState(null);
  const [listaCursos, setListaCursos] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");

  useEffect(() => {
    const fetchProfessor = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/professores/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setProfessor(dados);
        } else {
          console.error("Erro ao buscar professor");
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    const fetchCursos = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setListaCursos(dados);
        } else {
          console.error("Erro na requisição de cursos:", error);
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    fetchProfessor();
    fetchCursos();
  }, [id]);

  const handleEditClick = () => setEditMode(true);
  const handleCancelClick = () => {
    setEditMode(false);
    setCursoSelecionado("");
  };
  const handleChange = (e) =>
    setProfessor({ ...professor, [e.target.name]: e.target.value });

  const handleCursoChange = (index, value) => {
    const novosCursos = [...professor.cursos];
    novosCursos[index] = value;
    setProfessor({ ...professor, cursos: novosCursos });
  };

  const handleAddCurso = () =>
    setProfessor({
      ...professor,
      cursos: [...professor.cursos, cursoSelecionado],
    });

  const handleSaveClick = async () => {
    try {
      const resposta = await fetch(`http://localhost:5000/professores/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(professor),
      });

      if (resposta.ok) {
        setEditMode(false);
      } else {
        console.error("Erro ao salvar professor");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  if (!professor) {
    return <div>Carregando...</div>;
  }

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{professor.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={handleEditClick}>
            Editar
          </button>
        )}
      </div>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        {/* Informação do professor */}
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informação do professor</h4>
          <p>
            <strong>{professor.nome}</strong>
          </p>
          <p>{professor.email}</p>
          <p>{professor.morada}</p>
          <p>{professor.contacto}</p>
        </div>

        {/* Formulário de edição */}
        <div className="w-50 ps-4">
          <label className="fw-bold">Cursos que Leciona</label>
          {professor.cursos &&
            professor.cursos.map((curso, index) => (
              <div key={index} className="input-group mb-2">
                <input
                  type="text"
                  className="form-control"
                  value={curso}
                  onChange={(e) => handleCursoChange(index, e.target.value)}
                  disabled={!editMode}
                />
              </div>
            ))}
          {editMode && (
            <div>
              <select
                className="form-control mb-2"
                value={cursoSelecionado}
                onChange={(e) => setCursoSelecionado(e.target.value)}
              >
                <option value="">Selecione um curso</option>
                {listaCursos.map((c) => (
                  <option key={c.id} value={c.nome}>
                    {c.nome}
                  </option>
                ))}
              </select>
              <button
                className="btn btn-outline-secondary mt-2"
                onClick={handleAddCurso}
              >
                +
              </button>
            </div>
          )}

          {editMode && (
            <div className="d-flex justify-content-between mt-3">
              <button className="btn btn-danger" onClick={handleCancelClick}>
                Cancelar
              </button>
              <button className="btn btn-primary" onClick={handleSaveClick}>
                Salvar
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdmInfProf;
